  bio: z.string().trim().max(160, 'Bio cannot exceed 160 characters').optional(),
});

export type ActionState = {
  success: boolean;
  errors?: { username?: string[]; bio?: string[] };
  message?: string;
};

export async function updateProfileAction(prevState: ActionState, formData: FormData): Promise<ActionState> {
  const rawData = {
    username: formData.get('username'),
    bio: formData.get('bio') || undefined,
  };

  const validation = ProfileSchema.safeParse(rawData);
  if (!validation.success) {
    return {
      success: false,
      errors: validation.error.flatten().fieldErrors,
      message: 'Validation failed. Please check the form errors.',
    };
  }

  try {
    // Simulate updating user record in database
